using System;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "DiademOfMadnessOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/DiademOfMadness Omen Data")]
public class DiademOfMadnessOmenData : IncreasePurifyReceivedByEnemiesOmenData
{
	private const string increaseCorruptionByPlayerFromNonEnemiesID = "IncreaseCorruptionByPlayerFromNonEnemies";

	[Header("Diadem of Madness")]
	[SerializeField]
	private int additionalCorruptionAmount;

	public override void Initialize(OmenInstance omenInstance)
	{
		Func<int, CorruptionPurifyModifierEnum, GameObject, int> onPlayerCorruptedDiademOfMadnessAction = delegate(int corruptAmount, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum, GameObject source)
		{
			if (corruptionPurifyModifierEnum != CorruptionPurifyModifierEnum.ANOMALY && corruptionPurifyModifierEnum != CorruptionPurifyModifierEnum.CANTBEINCREASEDCORRUPTION && !ReferenceSingleton<BattleHandler>.Instance.IsSourceEnemy(source))
			{
				corruptAmount += additionalCorruptionAmount;
				omenInstance.EnqueueOmenFeedbackAndPlay();
			}
			return corruptAmount;
		};
		ReferenceSingleton<MiscOmensHandler>.Instance.OnPlayerCorruptedDiademOfMadnessAction = onPlayerCorruptedDiademOfMadnessAction;
		base.Initialize(omenInstance);
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<MiscOmensHandler>.Instance.OnPlayerCorruptedDiademOfMadnessAction = null;
		base.OmenRemoved();
	}

	public override string OmenConvertedDescription()
	{
		return GetIncreasePurifyReceivedByEnemiesLocalizedString() + "\n" + Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("IncreaseCorruptionByPlayerFromNonEnemies"), additionalCorruptionAmount);
	}
}
